    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    fib_numbers = [0, 0, 2, 0] + [0] * (n - 3)

    for i in range(4, n + 1):
        fib_numbers[i] = fib_numbers[i - 1] + fib_numbers[i - 2] + fib_numbers[i - 3] + fib_numbers[i - 4]

    return fib_numbers[n]

